package simpleserver.command;

import simpleserver.Color;
import simpleserver.Player;

public class HelpCommand extends AbstractCommand implements PlayerCommand {
  public HelpCommand() {
    super("help [COMMAND]", "List commands or get help for one command");
  }

  public void execute(Player player, String message) {
    String[] arguments = extractArguments(message);

    if (arguments.length > 0) {
      String prefix = commandPrefix();
      String commandName = arguments[0];
      if (!commandName.startsWith(prefix)) {
        commandName = prefix + commandName;
      }
      PlayerCommand command = parser.getPlayerCommand(commandName);
      player.addMessage(command.getHelpText(prefix));

      String[] aliases = player.getServer().permissions.getCommandAliases(command.getName());
      if (aliases.length > 0) {
        StringBuffer line = new StringBuffer();
        for (String alias : aliases) {
          line.append(commandPrefix());
          line.append(alias);
          line.append(" ");
        }
        player.addTCaptionedMessage("Aliases", line.toString());
      }
    } else {
      StringBuffer line = new StringBuffer();

      String prefix = commandPrefix();

      for (Object cmd : player.getServer().permissions.getAllCommands()) {
        String commandName = cmd.toString();
        parser.getPlayerCommand(commandName);

        if (player.getServer().permissions.commandIsHidden(commandName)
            || !player.commandAllowed(commandName)) {
          continue;
        }

        line.append(prefix);
        line.append(commandName);
        line.append(" ");
      }

      player.addTCaptionedMessage("Available Commands", line.toString());

      player.addTMessage(Color.GRAY, "Say %s command for details of a specific command.",
                         prefix + "help");

      // additional custom help text from helptext.txt
      String[] helplines = player.getServer().helptext.getHelpText().split("\n");
      player.addMessage(" ");
      for (String l : helplines) {
        player.addMessage(Color.WHITE, l);
      }
    }
  }
}

@SuppressWarnings("unchecked")
public class CommandParser {
  private final Map<String, PlayerCommand> playerCommands;
  private final Map<Class, PlayerCommand> playerCommandClasses;
  private final Map<String, ServerCommand> serverCommands;
  private final Map<Class, ServerCommand> serverCommandClasses;
  private final Options options;
  private final PermissionConfig permissions;

  public CommandParser(Options options, PermissionConfig permissions) {
    this.options = options;
    this.permissions = permissions;

    playerCommands = new HashMap<String, PlayerCommand>();
    playerCommandClasses = new HashMap<Class, PlayerCommand>();
    serverCommands = new HashMap<String, ServerCommand>();
    serverCommandClasses = new HashMap<Class, ServerCommand>();
    loadCommands(PlayerCommand.class, playerCommands, playerCommandClasses);
    loadCommands(ServerCommand.class, serverCommands, serverCommandClasses);
  }

  public PlayerCommand getPlayerCommand(Class<? extends PlayerCommand> c) {
    if (playerCommandClasses.containsKey(c)) {
      return playerCommandClasses.get(c);
    } else {
      return null;
    }
  }

  public PlayerCommand getPlayerCommand(String message) {
    if (message.startsWith(commandPrefix())) {
      PlayerCommand command = playerCommands.get(extractName(message, 1));
      if (command == null) {
        if (options.contains("alternateJarFile")) {
          return new ExternalCommand(extractName(message, 1));
        } else {
          System.out.println("Illegal command configuration for: " + message);
          command = playerCommands.get(null);
        }
      }

      return command;
    }

    return null;
  }

  public ServerCommand getServerCommand(String message) {
    return serverCommands.get(extractName(message, 0));
  }

  public ServerCommand getServerCommand(Class<? extends ServerCommand> c) {
    if (serverCommandClasses.containsKey(c)) {
      return serverCommandClasses.get(c);
    } else {
      return null;
    }
  }

  public Collection<PlayerCommand> getPlayerCommands() {
    return playerCommands.values();
  }

  public String commandPrefix() {
    if (options.getBoolean("useSlashes")) {
      return "/";
    } else {
      return "!";
    }
  }

  private String extractName(String message, int offset) {
    int splitIndex = message.indexOf(" ");
    if (splitIndex == -1) {
      splitIndex = message.length();
    }

    String name = message.substring(offset, splitIndex).toLowerCase();
    return permissions.lookupCommand(name);
  }

  private <T extends Command> void loadCommands(Class<T> type, Map<String, T> commands, Map<Class, T> commandClasses) {
    Reflections r = new Reflections("simpleserver", new SubTypesScanner());
    Set<Class<? extends T>> types = r.getSubTypesOf(type);

    for (Class<? extends T> commandType : types) {
      if (Modifier.isAbstract(commandType.getModifiers())) {
        continue;
      }

      T command;
      try {
        command = commandType.getConstructor().newInstance(new Object[] {});
        ((AbstractCommand) command).setParser(this);
      } catch (Exception e) {
        e.printStackTrace();
        System.out.println("Unexpected exception.  Skipping command "
            + commandType.getName());
        continue;
      }

      commands.put(command.getName(), command);
      commandClasses.put(command.getClass(), command);
    }
  }

